export function TodoList({ todos, onToggle, onRemove, clearCompleted, completedCount, activeCount }) {
  if (todos.length === 0) return <p>Nothing to do.</p>
  return (
    <>
      <ul>
        {todos.map((todo) => (
          <TodoItem key={todo.id} todo={todo} onToggle={onToggle} onRemove={onRemove} />
        ))}
      </ul>
      <footer>
        <span>{activeCount === 1 ? '1 item left' : `${activeCount} items left`}</span>
        {completedCount > 0 && (
          <button type="button" onClick={clearCompleted} disabled={completedCount === 0}>
            Clear completed
          </button>
        )}
      </footer>
    </>
  )
}
